const movementsBySource = `-- name: MovementsBySource :many
SELECT m.id, m.company_id, m.product_id, m.seq, m.move_date, m.qty, m.valuation, m.fixed_value, m.mirror_of, m.value, m.owned, m.posted_value, m.counter_account_id, m.project_id, m.qty_after, m.value_after, m.source_type, m.source_id, m.source_number, m.memo, m.created_at, m.cost_of, m.branch_id, m.department_id, EXISTS (SELECT 1 FROM inventory.movements r WHERE r.mirror_of = m.id) AS reversed
FROM inventory.movements m
WHERE m.company_id = $1 AND m.source_type = $2 AND m.source_id = $3
  AND m.mirror_of IS NULL
ORDER BY m.seq
`

type MovementsBySourceParams struct {
	CompanyID  uuid.UUID
	SourceType string
	SourceID   uuid.UUID
}

type MovementsBySourceRow struct {
	ID               uuid.UUID
	CompanyID        uuid.UUID
	ProductID        uuid.UUID
	Seq              *int64
	MoveDate         civil.Date
	Qty              money.Amount
	Valuation        string
	FixedValue       *money.Amount
	MirrorOf         *uuid.UUID
	Value            money.Amount
	Owned            bool
	PostedValue      money.Amount
	CounterAccountID *uuid.UUID
	ProjectID        *uuid.UUID
	QtyAfter         money.Amount
	ValueAfter       money.Amount
	SourceType       string
	SourceID         uuid.UUID
	SourceNumber     string
	Memo             string
	CreatedAt        time.Time
	CostOf           *uuid.UUID
	BranchID         *uuid.UUID
	DepartmentID     *uuid.UUID
	Reversed         bool
}

func (q *Queries) MovementsBySource(ctx context.Context, arg MovementsBySourceParams) ([]MovementsBySourceRow, error) {
	rows, err := q.db.Query(ctx, movementsBySource, arg.CompanyID, arg.SourceType, arg.SourceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MovementsBySourceRow
	for rows.Next() {
		var i MovementsBySourceRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.ProductID,
			&i.Seq,
			&i.MoveDate,
			&i.Qty,
			&i.Valuation,
			&i.FixedValue,
			&i.MirrorOf,
			&i.Value,
			&i.Owned,
			&i.PostedValue,
			&i.CounterAccountID,
			&i.ProjectID,
			&i.QtyAfter,
			&i.ValueAfter,
			&i.SourceType,
			&i.SourceID,
			&i.SourceNumber,
			&i.Memo,
			&i.CreatedAt,
			&i.CostOf,
			&i.BranchID,
			&i.DepartmentID,
			&i.Reversed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

