const updateProduct = `-- name: UpdateProduct :execrows
UPDATE inventory.products
SET code = $1, name = $2, kind = $3, unit = $4, sale_price = $5,
    purchase_price = $6, revenue_account_id = $7,
    expense_account_id = $8, inventory_account_id = $9,
    active = $10, version = version + 1
WHERE company_id = $11 AND id = $12 AND version = $13
`

type UpdateProductParams struct {
	Code               string
	Name               string
	Kind               string
	Unit               string
	SalePrice          money.Amount
	PurchasePrice      money.Amount
	RevenueAccountID   *uuid.UUID
	ExpenseAccountID   *uuid.UUID
	InventoryAccountID *uuid.UUID
	Active             bool
	CompanyID          uuid.UUID
	ID                 uuid.UUID
	Version            int32
}

func (q *Queries) UpdateProduct(ctx context.Context, arg UpdateProductParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateProduct,
		arg.Code,
		arg.Name,
		arg.Kind,
		arg.Unit,
		arg.SalePrice,
		arg.PurchasePrice,
		arg.RevenueAccountID,
		arg.ExpenseAccountID,
		arg.InventoryAccountID,
		arg.Active,
		arg.CompanyID,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

